def dependency_order(graph):
    nodes = set(graph)
    for dependencies in graph.values():
        nodes.update(dependencies)
    dependents = {node: set() for node in nodes}
    pending = {node: 0 for node in nodes}
    for node, dependencies in graph.items():
        unique = set(dependencies)
        pending[node] = len(unique)
        for prerequisite in unique:
            dependents[prerequisite].add(node)
    available = sorted(node for node in nodes if pending[node] == 0)
    result = []
    while available:
        node = available.pop(0)
        result.append(node)
        for dependent in sorted(dependents[node]):
            pending[dependent] -= 1
            if pending[dependent] == 0:
                available.append(dependent)
    if len(result) != len(nodes):
        raise ValueError("dependency cycle")
    return result
